    {page==='orders'&&<main className="content"><div className="pagehead"><span className="eyebrow">A LITTLE UPDATE</span><h1>Your <i>orders.</i></h1></div>{!user?<p>Please sign in to view your orders.</p>:orders.length?orders.map(o=><div className="ordercard" key={o.id}><div><b>Order #{o.id}</b><span>{new Date(o.created_at).toLocaleDateString('en-IN')}</span></div><div>{o.items.map(i=><p key={i.id}>{i.product_name}  x  {i.quantity}</p>)}</div><strong>{money(o.total)}</strong>{isStaff?<select aria-label="Update order status" value={o.status} onChange={e=>updateStatus(o.id,e.target.value)}>{[...orderTrackingSteps.map(step=><option key={step.status} value={step.status}>{step.label}</option>),<option key='cancelled' value='cancelled'>Cancelled</option>]}</select>:<span className="status">{(o.tracking_status||o.status)==="cancelled"?"Cancelled":orderTrackingSteps[orderTrackingStatusIndex[o.tracking_status||o.status]??0].label}</span>}<button className="textbtn" onClick={()=>toggleOrderDetails(o.id)}>{orderDetails[o.id] ? 'Hide details' : 'Track order'}</button>{orderDetails[o.id]&&<div className="order-detail"><div className="tracking-header"><span><b>Order tracking</b><small>Tracking code: {o.tracking_code}</small></span><span className="tracking-current-label">{(o.tracking_status||o.status)==="cancelled"?"Cancelled":orderTrackingSteps[orderTrackingStatusIndex[o.tracking_status||o.status]??0].label}</span>{o.tracking_demo&&<small className="tracking-demo-note">Demo tracking advances one stage each day.</small>}</div>{(o.tracking_status||o.status)==="cancelled"?<div className="tracking-cancelled">This order was cancelled. Contact customer care if you need help.</div>:<div className="tracking-timeline" aria-label="Order delivery progress">{orderTrackingSteps.map((step,index)=>{const currentIndex=orderTrackingStatusIndex[o.tracking_status||o.status]??0;const complete=index<currentIndex;const current=index===currentIndex;return <div className={`tracking-step ${complete?"complete":""} ${current?"current":""}`} key={step.status}><span className="tracking-marker" aria-hidden="true">{complete?String.fromCharCode(10003):index+1}</span><span className="tracking-step-copy"><b>{step.label}</b>{current&&<small>Current status : {step.description}</small>}{index===0&&<small>{new Date(o.created_at).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}</small>}</span></div>})}</div>}<div className="tracking-order-meta"><span>Delivery to: {o.full_name}, {o.address}, {o.city} {o.postal_code}</span><span>Payment: {o.payment_method} | {o.payment_status}</span>{o.coupon_code&&<span>Coupon {o.coupon_code} | saved {money(o.discount_amount)}</span>}</div></div>}</div>):<p>No orders yet. Your next favourite sofa is waiting.</p>}</main>}
