    {page==='admin'&&isStaff&&<main className="content"><div className="pagehead"><span className="eyebrow">STORE MANAGEMENT</span><h1>Admin <i>studio.</i></h1></div>{adminStats&&<div className="admin-stat-cards">{[['Sales',money(adminStats.sales)],['Orders',adminStats.orders],['Customers',adminStats.users],['Products',adminStats.products],['Pending orders',adminStats.pending_orders],['Low stock',adminStats.low_stock]].map(([label,value])=><article key={label}><span>{label}</span><b>{value}</b></article>)}</div>}<div className="adminlayout"><form className="summary" onSubmit={createProduct}><h3>Add a product</h3><input required placeholder="Product name" value={form.name||''} onChange={e=>setForm({...form,name:e.target.value})}/><input required placeholder="Unique slug e.g. cloud-3-seater" value={form.slug||''} onChange={e=>setForm({...form,slug:e.target.value})}/><select required value={form.category||''} onChange={e=>setForm({...form,category:e.target.value})}><option value="">Select category</option>{categories.map(c=><option value={c.id} key={c.id}>{c.parent_name?`${c.parent_name}  -  ${c.name}`:c.name}</option>)}</select><textarea required placeholder="Description" value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/><input required type="number" placeholder="Price in INR" value={form.price||''} onChange={e=>setForm({...form,price:e.target.value})}/><input placeholder="Image URL (optional)" value={form.image_url||''} onChange={e=>setForm({...form,image_url:e.target.value})}/><label className="upload-field">Upload a high-quality product photo<input type="file" accept="image/*" onChange={e=>setProductImage(e.target.files?.[0]||null)}/>{productImage&&<small>{productImage.name}</small>}</label><input placeholder="Material" value={form.material||''} onChange={e=>setForm({...form,material:e.target.value})}/><input type="number" placeholder="Stock" value={form.stock||''} onChange={e=>setForm({...form,stock:e.target.value})}/><button className="darkbtn full" disabled={busy}>Create product</button></form><div><h3>Products ({products.length})</h3><p className="muted">Upload a photo on the matching product row to update its primary image.</p>{products.map(p=><div className="adminrow product-adminrow" key={p.id}><img src={image(p)} alt=""/><div className="product-admin-info"><b>{p.name}</b><span>{money(p.price)}</span><label className="upload-small">{p.images?.length?'Replace product photo':'Add product photo'}<input type="file" accept="image/*" disabled={busy} onChange={e=>uploadProductImage(p,e.target.files?.[0])}/></label></div></div>)}<button className="outline" onClick={load}>Refresh products</button><p><a href="http://127.0.0.1:8000/admin/" target="_blank">Open Django admin</a></p></div></div></main>}
